const searchTab = 103795576;

// Let's search on Yahoo for more landscaper websites and review pages
const searches = [
  "top rated landscaping companies Dallas TX",
  "best landscaping services Fort Worth TX",
  "landscaping design contractors Dallas Fort Worth"
];

const candidates = [];

for (const q of searches) {
  await tool.navigate({ tabId: searchTab, url: "https://search.yahoo.com/search?p=" + encodeURIComponent(q) });
  await tool.wait_for({ tabId: searchTab, condition: "load_state", value: "load", timeout_ms: 4000 });

  const pageResults = await browserjs(searchTab, () => {
    const list = [];
    document.querySelectorAll('#web ol li').forEach(li => {
      const a = li.querySelector('h3 a, a.fz-20');
      const snippet = li.querySelector('.compText, p');
      if (a && a.href && !a.href.includes('yahoo.com')) {
        list.push({
          title: a.textContent.trim(),
          url: a.href,
          snippet: snippet ? snippet.textContent.trim() : ''
        });
      }
    });
    return list;
  });
  candidates.push(...pageResults);
}

console.log("Total raw candidates found:", candidates.length);
// Filter out aggregator/directory duplicates and get direct candidates
const filtered = candidates.filter(c => 
  !c.url.includes('wikipedia') && 
  !c.url.includes('dictionary') && 
  !c.url.includes('here.com')
);

console.log("Unique domains/links:", [...new Set(filtered.map(c => c.url))].slice(0, 20));

