const tabId = 103795576;
const queries = [
  "Rescue Air and Plumbing Dallas rating reviews",
  "Legacy Plumbing Frisco Dallas rating reviews",
  "Metro Flow Plumbing Dallas rating reviews"
];

const ratings = {};

for (const q of queries) {
  await tool.navigate({ tabId, url: "https://duckduckgo.com/?q=" + encodeURIComponent(q) });
  await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 6000 });
  const text = await browserjs(tabId, () => document.body.innerText);
  const match = text.match(/(\b[45]\.\d\b\s*(\([0-9,]+\)|\★|\/5)|[0-9,]+\s*reviews)/gi);
  ratings[q] = match ? match.slice(0, 5) : [];
}

console.log("Ratings found:", JSON.stringify(ratings, null, 2));

