  { tabId: 103795605, name: "GBW Electric" },
  { tabId: 103795606, name: "Olson Electric Service" },
  { tabId: 103795607, name: "4G Electrician" },
  { tabId: 103795608, name: "Cotton Electric Service" },
  { tabId: 103795609, name: "Electric Man Inc." }
];

const details = [];

for (const t of tabs) {
  const info = await browserjs(t.tabId, () => {
    const text = document.body.innerText;
    const match = text.match(/(\d(\.\d)?\s*(\/|\s*out of\s*)\s*5|\b[45]\.\d\b|\b\d[\d,]*\s*(reviews|ratings|stars))/gi);
    return {
      title: document.title,
      url: window.location.href,
      matches: match ? match.slice(0, 5) : []
    };
  });
  details.push({ ...t, ...info });
}

console.log(JSON.stringify(details, null, 2));

